  // ── L11.T1.7 — Partnerships: ledger, adjustments & final accounts ─────────
  "ACC.G11.T1.PARTLEDGER.A1": [
    mc("G11.PARTLEDGER.01", "The Appropriation Account divides the…", ["Net profit among the partners", "Sales among customers", "Stock among suppliers", "VAT among debtors"], "Net profit among the partners", "It shares net profit per the agreement.", ["ERR_ACC_APPROPRIATION"], 1),
    mc("G11.PARTLEDGER.02", "A provision for bad debts is created to…", ["Allow for debtors who may not pay", "Increase sales", "Pay the partners", "Record a fixed asset"], "Allow for debtors who may not pay", "It provides for likely uncollectable debts.", ["ERR_ACC_PROVISION"], 1),
    cloze("G11.PARTLEDGER.03", "Net profit is calculated in the Profit and Loss Account before being shared in the ______ account.", ["Appropriation", "Trading", "Capital", "Bank"], "Appropriation", "Net profit flows into the Appropriation Account.", ["ERR_ACC_APPROPRIATION"], 1),
    de("G11.PARTLEDGER.04", "Record interest on capital owed to Partner A.", [["appropriation", "Appropriation account"], ["currentA", "Current account: A"], ["bank", "Bank"], ["capitalA", "Capital: A"]], "appropriation", "currentA", "Interest on capital: Appropriation (debit), Current account: A (credit).", ["ERR_ACC_DOUBLE_ENTRY_SIDE"], 2),
    de("G11.PARTLEDGER.05", "Record the salary owed to Partner B.", [["appropriation", "Appropriation account"], ["currentB", "Current account: B"], ["bank", "Bank"], ["salaries", "Salaries"]], "appropriation", "currentB", "Partner salary: Appropriation (debit), Current account: B (credit).", ["ERR_ACC_DOUBLE_ENTRY_SIDE"], 2),
    eq("G11.PARTLEDGER.06", "The provision for bad debts is increased at year-end.", "-", "-", "0", "Net debtors (asset) fall; the increase is an expense reducing equity.", ["ERR_ACC_EQUATION"], 2),
    eq("G11.PARTLEDGER.07", "Interest on a loan from a partner is accrued (owing) at year-end.", "0", "-", "+", "The interest expense reduces equity; the amount owing is a liability.", ["ERR_ACC_EQUATION"], 2),
    eq("G11.PARTLEDGER.08", "An additional bad debt is written off at year-end.", "-", "-", "0", "Debtors (asset) fall; the bad debt is an expense reducing equity.", ["ERR_ACC_EQUATION"], 2),
    de("G11.PARTLEDGER.09", "Close the net profit to the Appropriation Account.", [["profitloss", "Profit and Loss account"], ["appropriation", "Appropriation account"], ["bank", "Bank"], ["capital", "Capital"]], "profitloss", "appropriation", "Net profit: Profit and Loss (debit), Appropriation (credit).", ["ERR_ACC_DOUBLE_ENTRY_SIDE"], 2),
    de("G11.PARTLEDGER.10", "Transfer Partner A's share of the remaining profit.", [["appropriation", "Appropriation account"], ["currentA", "Current account: A"], ["bank", "Bank"], ["capitalA", "Capital: A"]], "appropriation", "currentA", "Profit share: Appropriation (debit), Current account: A (credit).", ["ERR_ACC_DOUBLE_ENTRY_SIDE"], 2),
    mc("G11.PARTLEDGER.11", "After salaries and interest on capital, the remaining profit is shared in the…", ["Agreed profit-sharing ratio", "Order of age", "Ratio of drawings", "Equal halves always"], "Agreed profit-sharing ratio", "The balance is split in the agreed ratio.", ["ERR_ACC_PROFIT_SHARE"], 2),
    cloze("G11.PARTLEDGER.12", "A ______ for bad debts reduces the value of debtors shown in the Balance Sheet.", ["provision", "discount", "deposit", "drawing"], "provision", "The provision is netted against debtors.", ["ERR_ACC_PROVISION"], 2),
    mc("G11.PARTLEDGER.13", "Interest on a loan from a partner is treated as…", ["An expense (in the Profit and Loss Account)", "An appropriation of profit", "A fixed asset", "A capital contribution"], "An expense (in the Profit and Loss Account)", "Loan interest is an expense, unlike interest on capital.", ["ERR_ACC_INTEREST_LOAN"], 2),
    mc("G11.PARTLEDGER.14", "Partners' salaries in a partnership are…", ["An appropriation of profit", "A normal operating expense", "A fixed asset", "A current liability"], "An appropriation of profit", "Partner salaries appropriate profit.", ["ERR_ACC_APPROPRIATION"], 2),
    tf("G11.PARTLEDGER.15", "The Appropriation Account starts with the net profit from the Profit and Loss Account.", true, "Net profit is the opening figure of the Appropriation Account.", ["ERR_ACC_APPROPRIATION"], 2),
    mc("G11.PARTLEDGER.16", "If total appropriations exceed the net profit, partners may end up with…", ["Debit balances on their current accounts", "Extra capital", "More fixed assets", "Higher sales"], "Debit balances on their current accounts", "Over-distribution leaves debit current balances.", ["ERR_ACC_CURRENT_ACCOUNT"], 3),
    de("G11.PARTLEDGER.17", "Record cash drawings taken by Partner A during the year.", [["drawingsA", "Drawings: A"], ["bank", "Bank"], ["capitalA", "Capital: A"], ["sales", "Sales"]], "drawingsA", "bank", "Drawings: Drawings: A (debit), Bank (credit).", ["ERR_ACC_DOUBLE_ENTRY_SIDE"], 3),
    mc("G11.PARTLEDGER.18", "Year-end adjustments for a partnership include…", ["Depreciation, accruals, prepayments and provision for bad debts", "Only the bank balance", "Only sales", "Only drawings"], "Depreciation, accruals, prepayments and provision for bad debts", "The same adjustments as a sole trader, plus partner items.", ["ERR_ACC_ADJUSTMENTS"], 2),
    eq("G11.PARTLEDGER.19", "Consumable stores on hand are recorded at year-end (the adjustment).", "+", "+", "0", "An asset is created for unused stores and the expense reduced, raising equity.", ["ERR_ACC_EQUATION"], 3),
    mc("G11.PARTLEDGER.20", "Why prepare an Appropriation Account?", ["To divide the profit fairly per the partnership agreement", "To calculate VAT", "To list the debtors", "To replace the bank statement"], "To divide the profit fairly per the partnership agreement", "It allocates profit per the agreement.", ["ERR_ACC_APPROPRIATION"], 3),
  ],

