  // ── L11.T2.1 — Partnerships: analysis & interpretation ────────────────────
  "ACC.G11.T2.PARTINTERPRET.A1": [
    mc("G11.PARTINTERPRET.01", "The stock turnover rate measures…", ["How many times stock is sold and replaced in a period", "How much cash is in the bank", "The number of partners", "The VAT owed"], "How many times stock is sold and replaced in a period", "Turnover shows how fast stock moves.", ["ERR_ACC_STOCK_TURNOVER"], 1),
    mc("G11.PARTINTERPRET.02", "The debtors' collection period measures…", ["How long, on average, debtors take to pay", "How much stock is held", "The gearing of the business", "The VAT rate"], "How long, on average, debtors take to pay", "It shows the average days to collect.", ["ERR_ACC_DEBTORS_DAYS"], 1),
    cloze("G11.PARTINTERPRET.03", "A high stock turnover usually means stock is selling ______.", ["quickly", "slowly", "at a loss", "on credit"], "quickly", "Faster turnover means stock sells quickly.", ["ERR_ACC_STOCK_TURNOVER"], 1),
    tf("G11.PARTINTERPRET.04", "A long debtors' collection period can cause cash flow problems.", true, "Slow collection ties up cash.", ["ERR_ACC_DEBTORS_DAYS"], 1),
    mc("G11.PARTINTERPRET.05", "The debt-equity (gearing) ratio compares…", ["Borrowed funds to owners' equity", "Sales to cost of sales", "Cash to stock", "Debtors to creditors"], "Borrowed funds to owners' equity", "Gearing measures reliance on debt.", ["ERR_ACC_GEARING"], 2),
    mc("G11.PARTINTERPRET.06", "Cost of sales R600 000 and average stock R100 000. The stock turnover rate is…", ["6 times", "60 times", "0.6 times", "16 times"], "6 times", "R600 000 ÷ R100 000 = 6 times.", ["ERR_ACC_STOCK_TURNOVER"], 2),
    mc("G11.PARTINTERPRET.07", "Average debtors R40 000 and credit sales R365 000. The collection period is about…", ["40 days", "10 days", "365 days", "9 days"], "40 days", "R40 000 ÷ R365 000 × 365 = 40 days.", ["ERR_ACC_DEBTORS_DAYS"], 2),
    cmp("G11.PARTINTERPRET.08", "Compare two partnerships' efficiency.", "Source A: stock turnover 8 times; debtors collected in 25 days.", "Source B: stock turnover 2 times; debtors collected in 70 days.", [["s1", "Manages stock and debtors efficiently", "a_only"], ["s2", "Has slow-moving stock and slow collections", "b_only"], ["s3", "Can have these ratios calculated", "both"]], "Source A is efficient; Source B ties up cash in stock and debtors.", ["ERR_ACC_EFFICIENCY"], 3),
    mc("G11.PARTINTERPRET.09", "A very short creditors' payment period may mean the business…", ["Pays suppliers quickly and uses less credit", "Never pays suppliers", "Has no creditors", "Makes more sales"], "Pays suppliers quickly and uses less credit", "Paying fast reduces the use of supplier credit.", ["ERR_ACC_CREDITORS_DAYS"], 2),
    cloze("G11.PARTINTERPRET.10", "High gearing means the business relies heavily on ______ funds.", ["borrowed", "owners'", "cash", "stock"], "borrowed", "High gearing means more debt relative to equity.", ["ERR_ACC_GEARING"], 2),
    mc("G11.PARTINTERPRET.11", "Return on partners' equity measures…", ["Profit earned relative to the partners' equity", "Stock held", "Cash in the bank", "VAT paid"], "Profit earned relative to the partners' equity", "ROE relates profit to equity invested.", ["ERR_ACC_ROE"], 2),
    tf("G11.PARTINTERPRET.12", "A return on equity higher than the interest rate on savings is good for the partners.", true, "It beats simply leaving the money in the bank.", ["ERR_ACC_ROE"], 2),
    mc("G11.PARTINTERPRET.13", "Partners' total earnings include…", ["Salary, interest on capital and profit share", "Only drawings", "Only the bank balance", "Only sales"], "Salary, interest on capital and profit share", "Earnings combine salary, interest and profit share.", ["ERR_ACC_PARTNER_EARNINGS"], 2),
    mc("G11.PARTINTERPRET.14", "A rising debtors' collection period suggests…", ["Debtors are paying more slowly", "Debtors are paying faster", "Sales have stopped", "Stock is cheaper"], "Debtors are paying more slowly", "A longer period means slower collection.", ["ERR_ACC_DEBTORS_DAYS"], 3),
    cmp("G11.PARTINTERPRET.15", "Compare the gearing of two firms.", "Source A: debt-equity ratio 0.3:1.", "Source B: debt-equity ratio 1.5:1.", [["s1", "Relies mostly on its own equity (low risk)", "a_only"], ["s2", "Relies heavily on borrowing (higher risk)", "b_only"], ["s3", "Has a debt-equity ratio that can be assessed", "both"]], "Source A is low-geared and lower risk; Source B is highly geared.", ["ERR_ACC_GEARING"], 3),
    mc("G11.PARTINTERPRET.16", "A stock holding period of 60 days means stock is held about…", ["Two months before it is sold", "Two days", "Two years", "Sixty months"], "Two months before it is sold", "60 days ≈ two months.", ["ERR_ACC_STOCK_HOLDING"], 2),
    tf("G11.PARTINTERPRET.17", "Comparing this year's ratios to last year's shows the trend.", true, "Trend analysis compares across periods.", ["ERR_ACC_TREND"], 2),
    mc("G11.PARTINTERPRET.18", "If gearing is high and profits fall, the partners face…", ["Greater risk, as interest must still be paid", "No risk at all", "Lower expenses", "Higher sales"], "Greater risk, as interest must still be paid", "High gearing magnifies risk when profits drop.", ["ERR_ACC_GEARING"], 3),
    mc("G11.PARTINTERPRET.19", "Why interpret partnership financial statements?", ["To judge profitability, liquidity and risk", "To increase the VAT", "To replace the ledger", "To avoid keeping records"], "To judge profitability, liquidity and risk", "Interpretation informs decisions.", ["ERR_ACC_INTERPRET_PURPOSE"], 3),
    cloze("G11.PARTINTERPRET.20", "Return on partners' equity = net profit ÷ ______ × 100.", ["partners' equity", "sales", "cost of sales", "creditors"], "partners' equity", "ROE relates profit to partners' equity.", ["ERR_ACC_ROE"], 2),
  ],

